def numerical_letter_grade(grades):
    """
    Convert a list of GPA values into their corresponding letter grades.

    Parameters
    ----------
    grades : list[float]
        A list of GPA values.

    Returns
    -------
    list[str]
        A list of letter grades that correspond to the input GPAs.
    """
    grades = []
    for g in grades:
        if g == 4.0:
            grades.append('A+')
        elif g > 3.7:
            grades.append('A')
        elif g > 3.3:
            grades.append('A-')
        elif g > 3.0:
            grades.append('B+')
        elif g > 2.7:
            grades.append('B')
        elif g > 2.3:
            grades.append('B-')
        elif g > 2.0:
            grades.append('C+')
        elif g > 1.7:
            grades.append('C')
        elif g > 1.3:
            grades.append('C-')
        elif g > 1.0:
            grades.append('D+')
        elif g > 0.7:
            grades.append('D')
        elif g > 0.0:
            grades.append('D-')
        else:  # g <= 0.0
            grades.append('E')
    return grades
