import math

def skjkasdkd(lst):
    """Find the largest prime in the list and return the sum of its digits."""
    def is_prime(n: int) -> bool:
        """Return True if n is a prime number."""
        if n < 2:
            return False
        if n in (2, 3):
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        # Check divisibility by numbers of the form 6k ± 1
        limit = int(math.isqrt(n))
        i = 5
        while i <= limit:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num

    if max_prime is None:
        return 0

    # Sum the digits of the largest prime
    return sum(int(d) for d in str(max_prime))
